CREATE TABLE IF NOT EXISTS food_catalog (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL, aliases TEXT[] NOT NULL DEFAULT '{}', region TEXT NOT NULL DEFAULT 'Indian', category TEXT NOT NULL DEFAULT 'Everyday', diet TEXT NOT NULL DEFAULT 'vegetarian', meal_types TEXT[] NOT NULL DEFAULT '{}', serving_label TEXT NOT NULL DEFAULT '1 serving', serving_grams NUMERIC NOT NULL DEFAULT 100, calories NUMERIC NOT NULL DEFAULT 0, protein NUMERIC NOT NULL DEFAULT 0, carbs NUMERIC NOT NULL DEFAULT 0, fat NUMERIC NOT NULL DEFAULT 0, fiber NUMERIC NOT NULL DEFAULT 0, source_note TEXT NOT NULL DEFAULT 'Curated estimate; recipe and portion vary', estimate BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now())